-- BuildLens operational foundation. All user-facing data is tenant-scoped and append-only histories are protected.
create extension if not exists pgcrypto;

create type public.data_classification as enum ('PUBLIC','INTERNAL','CONFIDENTIAL','HIGHLY_CONFIDENTIAL');
create type public.project_status as enum ('PLANNING','ACTIVE','ON_HOLD','COMPLETED','CANCELLED');
create type public.task_status as enum ('NOT_STARTED','ASSIGNED','IN_PROGRESS','BLOCKED','PENDING_INSPECTION','REWORK_REQUIRED','COMPLETED','CANCELLED');
create type public.timer_status as enum ('NOT_STARTED','RUNNING','PAUSED','COMPLETED','EXPIRED','CANCELLED');

create table public.organizations (
  id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique,
  classification public.data_classification not null default 'CONFIDENTIAL', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid, updated_by uuid
);
create table public.roles (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete cascade, name text not null, description text, unique (organization_id,name));
create table public.permissions (id uuid primary key default gen_random_uuid(), key text not null unique, description text);
create table public.role_permissions (role_id uuid references public.roles(id) on delete cascade, permission_id uuid references public.permissions(id) on delete cascade, primary key(role_id,permission_id));
create table public.organization_members (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), user_id uuid not null references auth.users(id), role_id uuid references public.roles(id), status text not null default 'ACTIVE' check(status in ('ACTIVE','INACTIVE','INVITED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,user_id)
);
create table public.projects (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, project_code text not null, client text, location text, address text, start_date date, target_completion_date date, actual_completion_date date, status public.project_status not null default 'PLANNING', description text, classification public.data_classification not null default 'CONFIDENTIAL', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid, updated_by uuid, deleted_at timestamptz, deleted_by uuid, unique(organization_id,project_code)
);
create table public.villas (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), project_id uuid not null references public.projects(id), villa_number text not null, plot_number text, block text, phase text, cluster text, villa_type text, status text not null default 'PLANNING', client text, target_handover_date date, actual_handover_date date, latitude numeric(10,7), longitude numeric(10,7), notes text, classification public.data_classification not null default 'CONFIDENTIAL', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid, updated_by uuid, deleted_at timestamptz, deleted_by uuid, unique(project_id,villa_number)
);
create table public.villa_measurements (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_id uuid not null references public.villas(id), measurement_type text not null, value numeric(14,2) not null check(value >= 0), unit text not null check(unit in ('SQFT','SQM','FT','M')), unique(villa_id,measurement_type));
create table public.villa_levels (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_id uuid not null references public.villas(id), name text not null, level_number integer not null, unique(villa_id,level_number));
create table public.villa_rooms (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), villa_id uuid not null references public.villas(id), level_id uuid references public.villa_levels(id), room_type text not null, name text not null, area numeric(14,2) check(area >= 0), area_unit text default 'SQFT', specifications jsonb not null default '{}'::jsonb);
create table public.employees (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), user_id uuid references auth.users(id), employee_code text not null, full_name text not null, phone text, status text not null default 'ACTIVE', classification public.data_classification not null default 'HIGHLY_CONFIDENTIAL', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,employee_code));
create table public.teams (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, leader_employee_id uuid references public.employees(id), status text not null default 'ACTIVE', unique(organization_id,name));
create table public.employee_project_assignments (employee_id uuid references public.employees(id), project_id uuid references public.projects(id), organization_id uuid not null references public.organizations(id), primary key(employee_id,project_id));
create table public.employee_villa_assignments (employee_id uuid references public.employees(id), villa_id uuid references public.villas(id), organization_id uuid not null references public.organizations(id), primary key(employee_id,villa_id));
create table public.work_sections (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, active boolean not null default true, unique(organization_id,name));
create table public.work_categories (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), section_id uuid not null references public.work_sections(id), name text not null, unique(section_id,name));
create table public.vendors (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), company_name text not null, category text, status text not null default 'ACTIVE', classification public.data_classification not null default 'CONFIDENTIAL', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,company_name));
create table public.tasks (
  id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), project_id uuid not null references public.projects(id), villa_id uuid references public.villas(id), level_id uuid references public.villa_levels(id), room_id uuid references public.villa_rooms(id), work_section_id uuid references public.work_sections(id), responsible_employee_id uuid references public.employees(id), vendor_id uuid references public.vendors(id), assigned_team_id uuid references public.teams(id), name text not null, description text, status public.task_status not null default 'NOT_STARTED', priority text not null default 'MEDIUM' check(priority in ('LOW','MEDIUM','HIGH','CRITICAL')), progress numeric(5,2) not null default 0 check(progress between 0 and 100), planned_start_at timestamptz, planned_end_at timestamptz, actual_start_at timestamptz, actual_end_at timestamptz, quantity numeric(14,2) check(quantity >= 0), completed_quantity numeric(14,2) not null default 0 check(completed_quantity >= 0), unit text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid, updated_by uuid, check(planned_end_at is null or planned_start_at is null or planned_end_at > planned_start_at), check(actual_end_at is null or actual_start_at is null or actual_end_at >= actual_start_at), check(status <> 'COMPLETED' or progress = 100)
);
create table public.task_dependencies (task_id uuid references public.tasks(id) on delete cascade, depends_on_task_id uuid references public.tasks(id), organization_id uuid not null references public.organizations(id), dependency_status text not null default 'REQUIRED', primary key(task_id,depends_on_task_id), check(task_id <> depends_on_task_id));
create table public.task_assignments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), task_id uuid not null references public.tasks(id), employee_id uuid references public.employees(id), team_id uuid references public.teams(id), vendor_id uuid references public.vendors(id), assigned_at timestamptz not null default now(), check(num_nonnulls(employee_id,team_id,vendor_id)=1));
create table public.task_time_trackers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), task_id uuid not null unique references public.tasks(id), status public.timer_status not null default 'NOT_STARTED', planned_start_at timestamptz not null, planned_end_at timestamptz not null, estimated_work_minutes integer not null check(estimated_work_minutes > 0), started_at timestamptz, completed_at timestamptz, active_minutes integer not null default 0 check(active_minutes >= 0), paused_minutes integer not null default 0 check(paused_minutes >= 0), count_non_working_days boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid, updated_by uuid, check(planned_end_at > planned_start_at));
create table public.task_time_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), tracker_id uuid not null references public.task_time_trackers(id), event_type text not null check(event_type in ('CREATED','STARTED','PAUSED','RESUMED','EXTENDED','COMPLETED','EXPIRED')), occurred_at timestamptz not null default now(), actor_id uuid references auth.users(id), previous_value jsonb, new_value jsonb, reason text);
create table public.progress_updates (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), task_id uuid not null references public.tasks(id), employee_id uuid references public.employees(id), vendor_id uuid references public.vendors(id), previous_progress numeric(5,2) not null check(previous_progress between 0 and 100), new_progress numeric(5,2) not null check(new_progress between 0 and 100), quantity_completed numeric(14,2) default 0 check(quantity_completed >= 0), unit text, notes text, created_at timestamptz not null default now(), created_by uuid);
create table public.vendor_commitments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), vendor_id uuid not null references public.vendors(id), project_id uuid not null references public.projects(id), villa_id uuid references public.villas(id), task_id uuid references public.tasks(id), promised_date date not null, actual_date date, quantity numeric(14,2) check(quantity >= 0), status text not null default 'OPEN', evidence jsonb not null default '[]'::jsonb, check(actual_date is null or actual_date >= promised_date));
create table public.delay_reasons (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, attribution_type text not null, active boolean not null default true, unique(organization_id,name));
create table public.delay_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), task_id uuid references public.tasks(id), villa_id uuid references public.villas(id), reason_id uuid references public.delay_reasons(id), detected_by_timer boolean not null default false, started_at timestamptz not null, resolved_at timestamptz, duration_minutes integer check(duration_minutes >= 0), status text not null default 'OPEN', notes text, check(resolved_at is null or resolved_at >= started_at));
create table public.inspections (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), task_id uuid references public.tasks(id), villa_id uuid references public.villas(id), status text not null default 'PENDING', scheduled_at timestamptz, completed_at timestamptz, inspector_id uuid references public.employees(id), notes text);
create table public.attachments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), entity_type text not null, entity_id uuid not null, storage_path text not null unique, mime_type text not null, size_bytes bigint not null check(size_bytes >= 0), classification public.data_classification not null default 'CONFIDENTIAL', uploaded_by uuid references auth.users(id), uploaded_at timestamptz not null default now());
create table public.activity_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), event_type text not null, entity_type text not null, entity_id uuid not null, actor_id uuid references auth.users(id), occurred_at timestamptz not null default now(), payload jsonb not null default '{}'::jsonb);
create table public.audit_logs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id uuid, occurred_at timestamptz not null default now(), previous_value jsonb, new_value jsonb, request_id text, ip_metadata inet, user_agent text);

create index tasks_org_project_status_idx on public.tasks(organization_id, project_id, status);
create index tasks_villa_idx on public.tasks(villa_id);
create index activity_events_entity_idx on public.activity_events(organization_id, entity_type, entity_id, occurred_at desc);
create index audit_logs_org_occurred_idx on public.audit_logs(organization_id, occurred_at desc);
create index time_events_tracker_idx on public.task_time_events(tracker_id, occurred_at);

create or replace function public.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.organization_members m where m.organization_id = target_org and m.user_id = auth.uid() and m.status = 'ACTIVE') $$;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create trigger projects_updated before update on public.projects for each row execute function public.set_updated_at();
create trigger villas_updated before update on public.villas for each row execute function public.set_updated_at();
create trigger tasks_updated before update on public.tasks for each row execute function public.set_updated_at();
create trigger timers_updated before update on public.task_time_trackers for each row execute function public.set_updated_at();

-- RLS is deliberately enabled on every public table. Generic tenant policies apply only where org membership is enough; scoped assignment policies are added before exposing direct client reads.
alter table public.organizations enable row level security; alter table public.roles enable row level security; alter table public.permissions enable row level security; alter table public.role_permissions enable row level security; alter table public.organization_members enable row level security; alter table public.projects enable row level security; alter table public.villas enable row level security; alter table public.villa_measurements enable row level security; alter table public.villa_levels enable row level security; alter table public.villa_rooms enable row level security; alter table public.employees enable row level security; alter table public.teams enable row level security; alter table public.employee_project_assignments enable row level security; alter table public.employee_villa_assignments enable row level security; alter table public.work_sections enable row level security; alter table public.work_categories enable row level security; alter table public.vendors enable row level security; alter table public.tasks enable row level security; alter table public.task_dependencies enable row level security; alter table public.task_assignments enable row level security; alter table public.task_time_trackers enable row level security; alter table public.task_time_events enable row level security; alter table public.progress_updates enable row level security; alter table public.vendor_commitments enable row level security; alter table public.delay_reasons enable row level security; alter table public.delay_events enable row level security; alter table public.inspections enable row level security; alter table public.attachments enable row level security; alter table public.activity_events enable row level security; alter table public.audit_logs enable row level security;

do $$ declare t text; begin foreach t in array array['roles','organization_members','projects','villas','villa_measurements','villa_levels','villa_rooms','employees','teams','employee_project_assignments','employee_villa_assignments','work_sections','work_categories','vendors','tasks','task_dependencies','task_assignments','task_time_trackers','task_time_events','progress_updates','vendor_commitments','delay_reasons','delay_events','inspections','attachments','activity_events'] loop execute format('create policy %I on public.%I for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id))', t || '_tenant_access', t); end loop; end $$;
create policy organizations_member_read on public.organizations for select using(public.is_org_member(id));
create policy permissions_read on public.permissions for select using(auth.uid() is not null);
create policy role_permissions_read on public.role_permissions for select using(auth.uid() is not null);
create policy audit_logs_read on public.audit_logs for select using(public.is_org_member(organization_id));
-- no INSERT/UPDATE/DELETE audit policy: only the trusted backend service key may write immutable audit records.
